package v1

import (
	"encoding/json"
	"net/http"
	"path/filepath"
	"testing"

	"github.com/gin-gonic/gin"

	"github.com/luwa07832/deployment-tracker/internal/store"
)

func scratchRouter(t *testing.T) (*gin.Engine, *store.Store) {
	t.Helper()
	gin.SetMode(gin.TestMode)
	db, err := store.Open(filepath.Join(t.TempDir(), "v1.db"))
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { db.Close() })
	engine := gin.New()
	Register(engine, Dependencies{Store: db})
	return engine, db
}

func insertRecord(t *testing.T, db *store.Store, env, version, gate, point string, changes []store.ChangeEntry) string {
	t.Helper()
	rec := &store.ReleaseRecord{
		Environment: env, Version: version, GateStatus: gate,
		RollbackPoint: point, Changes: changes,
	}
	if err := db.InsertReleaseRecord(rec); err != nil {
		t.Fatal(err)
	}
	return rec.PublicID
}

func env(db *store.Store, key string) {
